function Customers({customers,transactions,setCustomers,setTransactions}:{customers:Customer[];transactions:CustomerTransaction[];setCustomers:(v:Customer[])=>void;setTransactions:(v:CustomerTransaction[])=>void}){const [form,setForm]=useState({name:"",phone:"",address:""}),[selected,setSelected]=useState(""),[amount,setAmount]=useState(0),[busy,setBusy]=useState(false),[dbTransactions,setDbTransactions]=useState<any[]>([]);const add=async()=>{if(!form.name||busy)return;setBusy(true);try{await apiCreateCustomer(form);setCustomers((await apiGetCustomers()) as Customer[]);setForm({name:"",phone:"",address:""})}catch(err){alert(err instanceof Error?err.message:"Customer could not be created.")}finally{setBusy(false)}};useEffect(()=>{if(selected)apiGetCustomerTransactions(selected).then(setDbTransactions).catch(()=>setDbTransactions([]));else setDbTransactions([])},[selected]);const payment=async()=>{const c=customers.find(x=>x.id===selected);if(!c||amount<=0||busy)return;setBusy(true);try{await apiRecordCustomerPayment(c.id,amount,"Khata payment");setCustomers((await apiGetCustomers()) as Customer[]);setDbTransactions(await apiGetCustomerTransactions(c.id));setTransactions([]);setAmount(0)}catch(err){const offlineCapable=!isOnline()||err instanceof TypeError;if(!offlineCapable){alert(err instanceof Error?err.message:"Payment failed.");return}try{await queueOfflineCustomerPayment({id:crypto.randomUUID(),customerId:c.id,amount,note:"Khata payment"});setCustomers(customers.map(x=>x.id===c.id?{...x,balance:Math.max(0,x.balance-amount)}:x));setAmount(0);alert("Internet unavailable — payment saved locally and will sync automatically.")}catch(queueErr){alert(queueErr instanceof Error?queueErr.message:"Offline payment could not be saved.")}}finally{setBusy(false)}};return <><section className="panel"><h2>Add Customer</h2><div className="formgrid"><label>NAME<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>PHONE<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>ADDRESS<input value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label></div><button className="primary" onClick={add}>Save Customer</button></section><section className="panel"><h2>Khata</h2><button onClick={()=>exportCustomersExcel(customers.map(c=>({Name:c.name,Phone:c.phone||"",Address:c.address||"",Outstanding:c.balance})))}>Export Customers Excel</button><div className="formgrid"><label>CUSTOMER<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select customer</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} — Rs. {c.balance}</option>)}</select></label><label>PAYMENT<input type="number" min="0" value={amount} onChange={e=>setAmount(Number(e.target.value))}/></label></div><button onClick={payment}>Record Payment</button><table><thead><tr><th>Name</th><th>Phone</th><th>Outstanding</th></tr></thead><tbody>{customers.map(c=><tr key={c.id}><td>{c.name}</td><td>{c.phone}</td><td>Rs. {c.balance}</td></tr>)}</tbody></table></section></>}

function Returns({products,sales,returns,movements,setProducts,setReturns,setMovements}:{products:Product[];sales:Sale[];returns:ReturnRecord[];movements:StockMovement[];setProducts:(v:Product[])=>void;setReturns:(v:ReturnRecord[])=>void;setMovements:(v:StockMovement[])=>void}){
 const [dbReturns,setDbReturns]=useState<any[]>([]),[saleId,setSaleId]=useState(""),[productId,setProductId]=useState(""),[replacementId,setReplacementId]=useState(""),[qty,setQty]=useState(1),[reason,setReason]=useState("Customer return"),[mode,setMode]=useState<"return"|"exchange">("return"),[refundMethod,setRefundMethod]=useState<"cash"|"card"|"bank"|"other">("cash"),[busy,setBusy]=useState(false);
 const sale=sales.find(s=>s.id===saleId);useEffect(()=>{apiGetReturns().then(setDbReturns).catch(()=>{})},[]);
 const originalItems=sale?.items||[];
 const productFor=(id:string)=>products.find(p=>p.id===id||p.variantId===id);
 const selectedItem=originalItems.find(i=>i.productId===productId||i.variantId===productId);
 const originalProduct=selectedItem?productFor(selectedItem.productId||selectedItem.variantId||""):undefined;
 const replacementProduct=products.find(p=>(p.variantId||p.id)===replacementId);
 const returnedValue=selectedItem&&originalProduct?selectedItem.price*qty:0;
 const replacementValue=replacementProduct?replacementProduct.price*qty:0;
 const difference=mode==="exchange"?replacementValue-returnedValue:0;
 const process=async()=>{
   if(busy||!sale||!selectedItem||!originalProduct||qty<1||qty>selectedItem.qty)return;
   if(mode==="exchange"&&(!replacementProduct||replacementId===(originalProduct.variantId||originalProduct.id)))return;
   setBusy(true);
   const r:ReturnRecord={id:crypto.randomUUID(),returnNo:"RET-"+Date.now(),saleId:sale.id,productId:originalProduct.id,qty,refundAmount:mode==="return"?returnedValue:Math.max(0,returnedValue-replacementValue),reason,createdAt:new Date().toISOString()};
   try{
     const result=await apiCreateReturn({
       saleId:sale.id,type:mode,refundAmount:r.refundAmount,refundMethod,
       items:[{variantId:originalProduct.variantId||originalProduct.id,quantity:qty,unitPrice:selectedItem.price}],
       exchangeItems:mode==="exchange"&&replacementProduct?[{variantId:replacementProduct.variantId||replacementProduct.id,quantity:qty,unitPrice:replacementProduct.price}]:[]
     });
     setProducts(await apiGetProducts());await apiGetReturns().then(setDbReturns).catch(()=>{});
     setMovements([{id:crypto.randomUUID(),productId:originalProduct.id,type:"sale_return",quantity:qty,reason,referenceId:r.id,createdAt:new Date().toISOString()},...movements]);
     setReturns([r,...returns]);
     alert(mode==="exchange"?(result.priceDifference>0?"Exchange completed. Customer pays Rs. "+result.priceDifference.toFixed(2)+".":result.refundAmount>0?"Exchange completed. Refund Rs. "+result.refundAmount.toFixed(2)+".":"Exchange completed. No price difference."):"Return completed. Refund Rs. "+result.refundAmount.toFixed(2)+".");
     setQty(1);setSaleId("");setProductId("");setReplacementId("");
   }catch(err){const offlineCapable=!isOnline()||err instanceof TypeError;if(!offlineCapable){alert(err instanceof Error?err.message:"Return failed.");return}try{if(mode==="return"){await queueOfflineReturn({id:r.id,saleId:sale.id,items:[{id:crypto.randomUUID(),productId:originalProduct.variantId||originalProduct.id,qty,refund:r.refundAmount,unitCost:originalProduct.cost}],refund:r.refundAmount,customerId:sale.customerId||null});}else if(replacementProduct){await queueOfflineExchange({id:r.id,saleId:sale.id,returned:[{id:crypto.randomUUID(),productId:originalProduct.variantId||originalProduct.id,qty}],replacement:[{id:crypto.randomUUID(),productId:replacementProduct.variantId||replacementProduct.id,qty,price:replacementProduct.price,unitCost:replacementProduct.cost}],difference,customerId:sale.customerId||null});}setReturns([r,...returns]);setProducts(products.map(p=>(p.id===originalProduct.id||(p.variantId&&p.variantId===originalProduct.variantId))?{...p,qty:p.qty+qty}:p));setMovements([{id:crypto.randomUUID(),productId:originalProduct.id,type:"sale_return",quantity:qty,reason,referenceId:r.id,createdAt:new Date().toISOString()},...movements]);alert("Internet unavailable — transaction saved locally and will sync automatically.");}catch(queueErr){alert(queueErr instanceof Error?queueErr.message:"Offline transaction could not be saved.");}}
   finally{setBusy(false)}
 };
 return <><section className="panel"><h2>Return / Exchange</h2>
   <div className="formgrid">
    <label>ORIGINAL INVOICE<select value={saleId} onChange={e=>{setSaleId(e.target.value);setProductId("");setReplacementId("")}}><option value="">Select sale</option>{sales.map(s=><option key={s.id} value={s.id}>{s.invoiceNo} — Rs. {s.total}</option>)}</select></label>
    <label>REFUND METHOD<select value={refundMethod} onChange={e=>setRefundMethod(e.target.value as "cash"|"card"|"bank"|"other")}><option value="cash">Cash</option><option value="card">Card</option><option value="bank">Bank</option><option value="other">Other</option></select></label>
    <label>RETURN ITEM<select value={productId} onChange={e=>{setProductId(e.target.value);setReplacementId("")}}><option value="">Select sold item</option>{originalItems.map(i=>{const p=productFor(i.productId||i.variantId||"");const id=p?.variantId||p?.id||i.variantId||i.productId;return <option key={id} value={id}>{p?.name||"Unknown"} — {p?.size||"No size"} / {p?.color||"No color"} — Sold {i.qty}</option>})}</select></label>
    <label>QTY<input type="number" min="1" max={selectedItem?.qty||1} value={qty} onChange={e=>setQty(Math.max(1,Number(e.target.value)))}/></label>
    <label>TYPE<select value={mode} onChange={e=>setMode(e.target.value as "return"|"exchange")}><option value="return">Return / Refund</option><option value="exchange">Exchange</option></select></label>
    {mode==="exchange"&&<label>REPLACEMENT ITEM<select value={replacementId} onChange={e=>setReplacementId(e.target.value)}><option value="">Select replacement</option>{products.filter(p=>(p.variantId||p.id)!==(originalProduct?.variantId||originalProduct?.id)).map(p=><option key={p.id} value={p.variantId||p.id}>{p.name} — {p.size||"No size"} / {p.color||"No color"} — Stock {p.qty} — Rs. {p.price}</option>)}</select></label>}
    <label>REASON<input value={reason} onChange={e=>setReason(e.target.value)}/></label>
   </div>
   {sale&&selectedItem&&<p><strong>Original value:</strong> Rs. {returnedValue.toFixed(2)} {mode==="exchange"&&replacementProduct&&<> • <strong>Replacement:</strong> Rs. {replacementValue.toFixed(2)} • <strong>{difference>0?"Customer pays":"Refund"}:</strong> Rs. {Math.abs(difference).toFixed(2)}</>}</p>}
   <button className="primary" onClick={process} disabled={busy}>{busy?"Processing...":mode==="exchange"?"Process Exchange":"Process Return"}</button>
 </section>
 <section className="panel"><h2>Return History</h2><button onClick={()=>exportReturnsExcel((dbReturns.length?dbReturns:returns).map((x:any)=>({ReturnNo:x.return_no||x.returnNo||"",Invoice:x.invoice_no||x.sale_id||"",Type:x.type||"return",Product:x.product_name||products.find((p:any)=>p.id===(x.product_id||x.productId))?.name||"",SKU:x.sku||"",Quantity:x.quantity??x.qty??0,Refund:x.refund_amount??x.refundAmount??0,PriceDifference:x.price_difference??0,Reason:x.reason||"",Date:x.created_at||x.createdAt||""})))}>Export Returns / Exchanges Excel</button>{returns.length===0&&dbReturns.length===0?<p>No returns yet.</p>:<table><thead><tr><th>Return</th><th>Type</th><th>Product</th><th>Qty</th><th>Refund</th><th>Date</th></tr></thead><tbody>{returns.map(r=><tr key={r.id}><td>{r.returnNo}</td><td>{r.saleId===saleId?mode:"Return"}</td><td>{products.find(p=>p.id===r.productId)?.name||"—"}</td><td>{r.qty}</td><td>Rs. {r.refundAmount}</td><td>{new Date(r.createdAt).toLocaleString()}</td></tr>)}</tbody></table>}</section></>
}

function Reports(){
 const [from,setFrom]=useState(new Date(Date.now()-6*86400000).toISOString().slice(0,10)),[to,setTo]=useState(new Date().toISOString().slice(0,10)),[summary,setSummary]=useState<any>(null),[sales,setSales]=useState<any>(null),[salesFilter,setSalesFilter]=useState("all"),[categoryFilter,setCategoryFilter]=useState("all"),[cashierFilter,setCashierFilter]=useState("all"),[profit,setProfit]=useState<any>(null),[returnImpact,setReturnImpact]=useState<any>(null),[payments,setPayments]=useState<any[]>([]),[products,setProducts]=useState<any[]>([]),[purchases,setPurchases]=useState<any[]>([]),[khata,setKhata]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const load=async()=>{setBusy(true);setError("");try{const [s,ds,pr,pu,k,cr,ca,pp,ri,pm]=await Promise.all([apiGetReportSummary(from,to),apiGetSalesReport(from,to),apiGetProductReport(from,to),apiGetPurchaseReport(from,to),apiGetKhataReport(),getCategoryReport(from,to),getCashierReport(from,to),getProfitReport(from,to),getReturnProfitImpact(from,to),getPaymentReport(from,to)]);setSummary(s);setSales({...ds,categories:cr,cashiers:ca});setProfit(pp);setReturnImpact(ri);setPayments(pm);setProducts(pr);setPurchases(pu);setKhata(k)}catch(err){setError(err instanceof Error?err.message:"Reports could not be loaded.")}finally{setBusy(false)}};
 useEffect(()=>{load()},[]);
 const printTable=(title:string,headers:string[],rows:string[][])=>{const w=window.open("","_blank","width=1000,height=800");if(!w)return;w.document.write("<html><head><title>"+title+"</title><style>body{font-family:Arial;padding:24px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}h1{margin-bottom:4px}</style></head><body><h1>"+title+"</h1><p>"+from+" to "+to+"</p><table><thead><tr>"+headers.map(h=>"<th>"+h+"</th>").join("")+"</tr></thead><tbody>"+rows.map(row=>"<tr>"+row.map(x=>"<td>"+x+"</td>").join("")+"</tr>").join("")+"</tbody></table><script>window.print()</script></body></html>");w.document.close()};
 const exportCsv=(name:string,headers:string[],rows:string[][])=>{const esc=(x:string)=>'"'+String(x).replace(/"/g,'""')+'"';const csv=[headers,...rows].map(r=>r.map(esc).join(",")).join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download=name+".csv";a.click();URL.revokeObjectURL(a.href)};
 return <><section className="panel"><h2>Reports</h2><div className="buttonrow"><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),d.getMonth(),d.getDate()).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>Today</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getTime()-6*86400000).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>Last 7 Days</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>This Month</button><button onClick={()=>{const d=new Date();setFrom(new Date(d.getFullYear(),0,1).toISOString().slice(0,10));setTo(d.toISOString().slice(0,10))}}>This Year</button></div><div className="formgrid"><label>FROM<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>TO<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><button className="primary" onClick={load} disabled={busy}>{busy?"Loading...":"Refresh Reports"}</button>{error&&<p>{error}</p>}</section>
 {summary&&<div className="grid">{[["Sales","Rs. "+Number(summary.sales?.sales_total||0).toFixed(2)],["Invoices",String(summary.sales?.invoices||0)],["Discounts","Rs. "+Number(summary.sales?.discounts||0).toFixed(2)],["Gross Profit","Rs. "+Number(summary.profit?.gross_profit||0).toFixed(2)],["Inventory Cost","Rs. "+Number(summary.inventory?.cost_value||0).toFixed(2)],["Retail Value","Rs. "+Number(summary.inventory?.retail_value||0).toFixed(2)]].map(([a,b])=><section className="card" key={a}><span>{a}</span><strong>{b}</strong></section>)}</div>}
 {sales&&<><section className="panel"><div className="formgrid"><label>Payment Filter<select value={salesFilter} onChange={e=>setSalesFilter(e.target.value)}><option value="all">All</option>{payments.map(x=><option key={x.method} value={x.method}>{x.method}</option>)}</select></label><label>Category Filter<select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="all">All</option>{(sales?.categories||[]).map((x:any)=><option key={x.category} value={x.category}>{x.category}</option>)}</select></label><label>Cashier Filter<select value={cashierFilter} onChange={e=>setCashierFilter(e.target.value)}><option value="all">All</option>{(sales?.cashiers||[]).map((x:any)=><option key={x.cashier} value={x.cashier}>{x.cashier}</option>)}</select></label></div><h2>Payment Method Breakdown</h2><table><thead><tr><th>Method</th><th>Transactions</th><th>Total</th></tr></thead><tbody>{payments.filter(x=>salesFilter==="all"||x.method===salesFilter).map(x=><tr key={x.method}><td>{x.method}</td><td>{x.transactions}</td><td>Rs. {Number(x.total||0).toFixed(2)}</td></tr>)}</tbody></table></section><section className="panel"><h2>Returns / Exchange Profit Impact</h2>{returnImpact&&<div className="grid">{[["Returned Sales","Rs. "+Number(returnImpact.returned_sales||0).toFixed(2)],["Returned Cost","Rs. "+Number(returnImpact.returned_cost||0).toFixed(2)],["Exchange Sales","Rs. "+Number(returnImpact.exchange_sales||0).toFixed(2)],["Exchange Cost","Rs. "+Number(returnImpact.exchange_cost||0).toFixed(2)],["Net Sales Impact","Rs. "+Number(returnImpact.net_sales_impact||0).toFixed(2)],["Gross Profit Impact","Rs. "+Number(returnImpact.gross_profit_impact||0).toFixed(2)],["Transactions",String(returnImpact.transactions||0)]].map(([k,v])=><section className="card" key={k}><span>{k}</span><strong>{v}</strong></section>)}</div>}</section><section className="panel"><h2>Profit Analysis</h2>{profit&&<><div className="grid">{[["Gross Sales","Rs. "+Number(profit.summary.gross_sales||0).toFixed(2)],["Discounts","Rs. "+Number(profit.summary.discounts||0).toFixed(2)],["Net Sales","Rs. "+Number(profit.summary.net_sales||0).toFixed(2)],["COGS","Rs. "+Number(profit.summary.cogs||0).toFixed(2)],["Gross Profit","Rs. "+Number(profit.summary.gross_profit||0).toFixed(2)],["Margin",Number(profit.summary.margin_percent||0).toFixed(2)+"%"]].map(([k,v])=><section className="card" key={k}><span>{k}</span><strong>{v}</strong></section>)}</div><button onClick={()=>exportReportExcel("Profit","stockdone-profit-report.xlsx",profit.daily as any)}>Export Profit Excel</button><button onClick={()=>printTable("Profit Report",["Date","Gross Sales","Discounts","Net Sales","COGS","Gross Profit","Margin %"],profit.daily.map((x:any)=>[x.date,"Rs. "+x.gross_sales,"Rs. "+x.discounts,"Rs. "+x.net_sales,"Rs. "+x.cogs,"Rs. "+x.gross_profit,x.margin_percent+"%"]))}>Print Profit Report</button></>}</section><section className="panel"><h2>Sales by Day</h2><button onClick={()=>exportReportExcel("Sales","stockdone-sales-report.xlsx",(sales?.daily||[]).map((x:any)=>({Date:x.date,Invoices:x.invoices,Sales:x.total,Discounts:x.discounts})))}>Export Excel</button> <button onClick={()=>exportCsv("sales-report",["Date","Invoices","Sales","Discounts"],sales.daily.map((x:any)=>[x.date,x.invoices,x.total,x.discounts]))}>Export CSV</button> <button onClick={()=>printTable("Sales Report",["Date","Invoices","Sales","Discounts"],sales.daily.map((x:any)=>[x.date,String(x.invoices),"Rs. "+x.total,"Rs. "+x.discounts]))}>Print</button><table><thead><tr><th>Date</th><th>Invoices</th><th>Sales</th><th>Discounts</th></tr></thead><tbody>{sales.daily.map((x:any)=><tr key={x.date}><td>{x.date}</td><td>{x.invoices}</td><td>Rs. {x.total}</td><td>Rs. {x.discounts}</td></tr>)}</tbody></table><h3>Payment Methods</h3><table><thead><tr><th>Method</th><th>Invoices</th><th>Total</th></tr></thead><tbody>{sales.payments.map((x:any)=><tr key={x.method}><td>{x.method}</td><td>{x.invoices}</td><td>Rs. {x.total}</td></tr>)}</tbody></table></section></>}
 <section className="panel"><h2>Category Performance</h2><table><thead><tr><th>Category</th><th>Units</th><th>Sales</th><th>Cost</th><th>Gross Profit</th></tr></thead><tbody>{(sales?.categories||[]).filter((x:any)=>categoryFilter==="all"||x.category===categoryFilter).map((x:any)=><tr key={x.category}><td>{x.category}</td><td>{x.units}</td><td>Rs. {x.sales}</td><td>Rs. {x.cost}</td><td>Rs. {x.gross_profit}</td></tr>)}</tbody></table><h2>Cashier Performance</h2><table><thead><tr><th>Cashier</th><th>Invoices</th><th>Sales</th><th>Discounts</th></tr></thead><tbody>{(sales?.cashiers||[]).filter((x:any)=>cashierFilter==="all"||x.cashier===cashierFilter).map((x:any)=><tr key={x.cashier}><td>{x.cashier}</td><td>{x.invoices}</td><td>Rs. {x.sales}</td><td>Rs. {x.discounts}</td></tr>)}</tbody></table></section><section className="panel"><h2>Product Performance</h2><button onClick={()=>exportReportExcel("Products","stockdone-product-report.xlsx",products.map((x:any)=>({Product:x.name,SKU:x.sku,Size:x.size||"",Color:x.color||"",Units:x.units,Sales:x.sales,Cost:x.cost,GrossProfit:x.gross_profit})))}>Export Excel</button> <button onClick={()=>exportCsv("product-report",["Product","SKU","Size","Color","Units","Sales","Cost","Gross Profit"],products.map(x=>[x.name,x.sku,x.size||"",x.color||"",x.units,x.sales,x.cost,x.gross_profit]))}>Export CSV</button> <button onClick={()=>printTable("Product Report",["Product","SKU","Size","Color","Units","Sales","Cost","Profit"],products.map(x=>[x.name,x.sku,x.size||"",x.color||"",String(x.units),"Rs. "+x.sales,"Rs. "+x.cost,"Rs. "+x.gross_profit]))}>Print</button><table><thead><tr><th>Product</th><th>SKU</th><th>Size</th><th>Color</th><th>Units</th><th>Sales</th><th>Gross Profit</th></tr></thead><tbody>{products.map((x:any)=><tr key={x.sku+"-"+x.size+"-"+x.color}><td>{x.name}</td><td>{x.sku}</td><td>{x.size||"—"}</td><td>{x.color||"—"}</td><td>{x.units}</td><td>Rs. {x.sales}</td><td>Rs. {x.gross_profit}</td></tr>)}</tbody></table></section>
 <section className="panel"><h2>Purchases</h2><button onClick={()=>exportReportExcel("Purchases","stockdone-purchase-report.xlsx",purchases.map((x:any)=>({Invoice:x.invoice_no,Supplier:x.supplier||"",Date:x.purchase_date,Total:x.total,PaymentMethod:x.payment_method||"credit",Paid:x.paid_amount??0,Outstanding:x.outstanding??(Number(x.total)-Number(x.paid_amount||0))})))}>Export Excel</button> <button onClick={()=>exportCsv("purchase-report",["Invoice","Supplier","Date","Total","Payment Method","Paid","Outstanding"],purchases.map(x=>[x.invoice_no,x.supplier||"",x.purchase_date,x.total,x.payment_method||"credit",x.paid_amount??0,x.outstanding??(Number(x.total)-Number(x.paid_amount||0))]))}>Export CSV</button><table><thead><tr><th>Invoice</th><th>Supplier</th><th>Date</th><th>Total</th><th>Payment</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody>{purchases.map((x:any)=><tr key={x.invoice_no}><td>{x.invoice_no}</td><td>{x.supplier||"—"}</td><td>{new Date(x.purchase_date).toLocaleString()}</td><td>Rs. {x.total}</td><td>{x.payment_method||"credit"}</td><td>Rs. {x.paid_amount??0}</td><td>Rs. {x.outstanding??(Number(x.total)-Number(x.paid_amount||0))}</td></tr>)}</tbody></table></section>
 <section className="panel"><h2>Khata / Outstanding</h2><button onClick={()=>exportReportExcel("Khata","stockdone-khata-report.xlsx",khata.map((x:any)=>({Customer:x.name,Phone:x.phone||"",Balance:x.balance,CreditLimit:x.credit_limit})))}>Export Excel</button><button onClick={()=>exportCsv("khata-report",["Customer","Phone","Balance","Credit Limit"],khata.map(x=>[x.name,x.phone||"",x.balance,x.credit_limit]))}>Export CSV</button><button onClick={()=>printTable("Khata Report",["Customer","Phone","Balance","Credit Limit"],khata.map(x=>[x.name,x.phone||"","Rs. "+x.balance,"Rs. "+x.credit_limit]))}>Print</button><table><thead><tr><th>Customer</th><th>Phone</th><th>Outstanding</th><th>Credit Limit</th></tr></thead><tbody>{khata.map(x=><tr key={x.id}><td>{x.name}</td><td>{x.phone||"—"}</td><td>Rs. {x.balance}</td><td>Rs. {x.credit_limit}</td></tr>)}</tbody></table></section></>
}

function AdminGate({session,children}:{session:User;children:any}){const [unlocked,setUnlocked]=useState(false),[password,setPassword]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState("");
if(unlocked)return <>{children}</>;
const unlock=async()=>{if(!password||busy)return;setBusy(true);setError("");try{const local=authStorage.login(session.username,password);if(local&&local.role==="owner"){setUnlocked(true);return}const r=await apiLogin(session.username,password);if(r.user.role!=="owner")throw new Error("Owner verification required.");setApiToken(r.token);setUnlocked(true)}catch(e){setError("Incorrect admin password. Use the same Owner password used for login.")}finally{setBusy(false)}};
return <section className="panel"><h2>Admin Verification</h2><p>Enter the same Owner password you use to sign in. There is no separate Admin password.</p><div className="formgrid"><label>OWNER PASSWORD<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void unlock()}} autoFocus/></label></div>{error&&<p className="error">{error}</p>}<button className="primary" onClick={()=>void unlock()} disabled={busy||!password}>{busy?"Verifying...":"Unlock Admin Area"}</button></section>}function HowToUse(){return <section className="panel"><h2>How to Use</h2><p>Quick guide for daily StockDone work.</p><h3>English</h3><ol><li>Business Information → complete your business name, phone, address and invoice details.</li><li>Categories / Products → add garments with category, size, color, SKU, barcode, cost and selling price.</li><li>Opening Stock → enter the starting quantity for each product or variant.</li><li>Barcode Scanner → connect a USB scanner; scan a barcode or SKU in POS to add the item quickly.</li><li>Printer → select the configured receipt/A4 printer and test printing before the first sale.</li><li>First Sale → scan/search products, review the cart, apply an allowed discount, select the customer/payment method, receive payment and complete the sale.</li><li>Inventory → check current stock, low-stock items and stock movement history.</li><li>Purchases → select a supplier, enter purchased items and quantities, then receive stock.</li><li>Customers / Khata → create a customer, record credit sales and payments, and review the transaction history.</li><li>Returns / Exchange → use the original invoice, select the returned item and quantity, then process the refund or exchange.</li><li>Reports → review sales, purchases, inventory, payments and profit for the selected period.</li><li>Backup / Restore → use the available backup tools when you need a local safety copy.</li></ol><hr/><h3>Roman Urdu</h3><ol><li>Business Information mein business ka naam, phone, address aur invoice ki details complete karein.</li><li>Categories / Products mein garment ki category, size, color, SKU, barcode, cost aur selling price add karein.</li><li>Opening Stock mein har product ya variant ki shuruati quantity enter karein.</li><li>Barcode Scanner mein USB scanner connect karein; POS mein barcode ya SKU scan karke item foran cart mein add karein.</li><li>Printer mein receipt ya A4 printer select karein aur pehli sale se pehle test print kar lein.</li><li>First Sale mein products scan/search karein, cart check karein, allowed discount lagayein, customer/payment method select karein, payment receive karein aur sale complete karein.</li><li>Inventory mein current stock, low-stock items aur stock movement history check karein.</li><li>Purchases mein supplier select karein, purchased items aur quantity enter karein aur stock receive karein.</li><li>Customers / Khata mein customer banayein, credit sale aur payments record karein aur transaction history dekhein.</li><li>Returns / Exchange mein original invoice use karein, returned item aur quantity select karein, phir refund ya exchange process karein.</li><li>Reports mein selected period ki sales, purchases, inventory, payments aur profit check karein.</li><li>Backup / Restore mein zaroorat ke waqt local safety backup use karein.</li></ol></section>}

function Transfers({products}:{products:Product[]}){const [branches,setBranches]=useState<any[]>([]),[transfers,setTransfers]=useState<any[]>([]),[to,setTo]=useState(""),[productId,setProductId]=useState(""),[qty,setQty]=useState(1),[busy,setBusy]=useState(false);useEffect(()=>{Promise.all([apiGetBranches(),apiGetStockTransfers()]).then(([b,t])=>{setBranches(b);setTransfers(t)}).catch(()=>{})},[]);const send=async()=>{const p=products.find(x=>(x.variantId||x.id)===productId);if(!to||!p||qty<1||busy)return;setBusy(true);try{await apiCreateStockTransfer({toBranchId:to,items:[{variantId:p.variantId||p.id,quantity:qty}]});alert("Transfer sent successfully.");setQty(1);apiGetStockTransfers().then(setTransfers).catch(()=>{})}catch(e){alert(e instanceof Error?e.message:"Transfer failed.")}finally{setBusy(false)}};return <><section className="panel"><h2>Stock Transfer</h2><p>Send stock from the current branch to another branch/warehouse.</p><div className="formgrid"><label>DESTINATION<select value={to} onChange={e=>setTo(e.target.value)}><option value="">Select branch</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name} ({b.code})</option>)}</select></label><label>PRODUCT / VARIANT<select value={productId} onChange={e=>setProductId(e.target.value)}><option value="">Select product</option>{products.map(p=><option key={p.id} value={p.variantId||p.id}>{p.name} — {p.sku} — {p.size||"No size"} / {p.color||"No color"} (Stock {p.qty})</option>)}</select></label><label>QUANTITY<input type="number" min="1" value={qty} onChange={e=>setQty(Math.max(1,Number(e.target.value)))}/></label></div><button className="primary" onClick={send} disabled={busy}>{busy?"Sending...":"Send Transfer"}</button></section><section className="panel"><h2>Transfer History</h2>{!transfers.length?<p>No transfers yet.</p>:<table><thead><tr><th>Date</th><th>From</th><th>To</th><th>Status</th><th>Action</th></tr></thead><tbody>{transfers.map(t=><tr key={t.id}><td>{new Date(t.created_at).toLocaleString()}</td><td>{t.from_branch}</td><td>{t.to_branch}</td><td>{t.status}</td><td>{t.status==="sent"?<button onClick={async()=>{try{await apiReceiveStockTransfer(t.id);setTransfers(await apiGetStockTransfers())}catch(e){alert(e instanceof Error?e.message:"Receive failed.")}}}>Receive</button>: "—"}</td></tr>)}</tbody></table>}</section></>}

function ScannerSettingsPanel(){const [s,setS]=useState(getScannerSettings());const save=()=>{saveScannerSettings(s);alert("Scanner settings saved.")};return <section className="panel"><h3>Barcode Scanner</h3><label><input type="checkbox" checked={s.enabled} onChange={e=>setS({...s,enabled:e.target.checked})}/> Enable scanner</label><label><input type="checkbox" checked={s.sound} onChange={e=>setS({...s,sound:e.target.checked})}/> Scan sound</label><label><input type="checkbox" checked={s.autoFocus} onChange={e=>setS({...s,autoFocus:e.target.checked})}/> Auto-focus POS scanner</label><label>SCAN DELAY (ms)<input type="number" min="0" max="500" value={s.delayMs} onChange={e=>setS({...s,delayMs:Math.max(0,Math.min(500,Number(e.target.value)))})}/></label><button onClick={save}>Save Scanner Settings</button><button onClick={scannerBeep}>Test Scan Sound</button></section>}
function MasterDataPanel(){
 const builtin=[{id:"categories",label:"Categories",icon:"CAT"},{id:"brands",label:"Brands",icon:"BR"},{id:"subCategories",label:"Sub-Categories",icon:"SUB"},{id:"floors",label:"Floors",icon:"FL"},{id:"warehouses",label:"Warehouses",icon:"WH"}];
 const [types,setTypes]=useState<any[]>([]),[selected,setSelected]=useState("categories"),[items,setItems]=useState<any[]>([]),[newType,setNewType]=useState(""),[newItem,setNewItem]=useState(""),[search,setSearch]=useState(""),[editing,setEditing]=useState<string|null>(null),[editName,setEditName]=useState(""),[editingType,setEditingType]=useState<string|null>(null),[editTypeName,setEditTypeName]=useState(""),[busy,setBusy]=useState(false);
 const loadTypes=async()=>{try{const x=await getMasterTypes();const byId=new Map<string,any>();[...builtin,...x].forEach(t=>byId.set(t.id,{...(byId.get(t.id)||{}),...t}));setTypes(Array.from(byId.values()).filter(t=>t.active!==false))}catch{setTypes(builtin)}};
 const load=async()=>{try{setItems(await getMasterData(selected))}catch{setItems([])}};
 useEffect(()=>{void loadTypes()},[]);
 useEffect(()=>{void load()},[selected]);
 const selectedType=types.find(t=>t.id===selected)||builtin.find(t=>t.id===selected)||{id:selected,label:selected};
 const activeItems=items.filter(x=>x.active!==false),inactiveItems=items.filter(x=>x.active===false);
 const filtered=items.filter(x=>String(x.name||"").toLowerCase().includes(search.trim().toLowerCase()));
 const addType=async()=>{if(!newType.trim()||busy)return;setBusy(true);try{const x=await createMasterType(newType.trim());setTypes(v=>[...v,x]);setSelected(x.id);setNewType("")}catch(e){alert(e instanceof Error?e.message:"Could not add master list.")}finally{setBusy(false)}};
 const renameType=async(t:any)=>{if(!editTypeName.trim()||busy)return;setBusy(true);try{const x=await updateMasterType(t.id,{label:editTypeName.trim(),active:t.active!==false});setTypes(v=>v.map(y=>y.id===t.id?{...y,...x}:y));setEditingType(null);setEditTypeName("")}catch(e){alert(e instanceof Error?e.message:"Could not rename master.")}finally{setBusy(false)}};
 const toggleType=async(t:any)=>{if(busy)return;setBusy(true);try{const x=await updateMasterType(t.id,{label:String(t.label||t.name),active:t.active===false});setTypes(v=>v.map(y=>y.id===t.id?{...y,...x}:y));if(x.active===false&&selected===t.id){const first=types.find(y=>y.id!==t.id&&y.active!==false);if(first)setSelected(first.id)} }catch(e){alert(e instanceof Error?e.message:"Could not update master.")}finally{setBusy(false)}};
 const addItem=async()=>{if(!newItem.trim()||busy)return;setBusy(true);try{await createMasterData({type:selected,name:newItem.trim()});setNewItem("");await load()}catch(e){alert(e instanceof Error?e.message:"Could not add item.")}finally{setBusy(false)}};
 const toggle=async(x:any)=>{if(busy)return;setBusy(true);try{await updateMasterData(selected,x.id,{name:x.name,active:x.active===false});await load()}catch(e){alert(e instanceof Error?e.message:"Could not update item.")}finally{setBusy(false)}};
 const rename=async(x:any)=>{if(!editName.trim()||busy)return;setBusy(true);try{await updateMasterData(selected,x.id,{name:editName.trim(),active:x.active!==false});setEditing(null);setEditName("");await load()}catch(e){alert(e instanceof Error?e.message:"Could not rename item.")}finally{setBusy(false)}};
 return <section className="master-data-page">
  <div className="master-hero"><div><span className="eyebrow">MASTER DATA</span><h2>Manage your store lists</h2><p>Categories, brands, sub-categories, floors, warehouses aur custom masters ek jagah manage karein.</p></div><div className="master-stats"><div><strong>{activeItems.length}</strong><span>Active</span></div><div><strong>{inactiveItems.length}</strong><span>Archived</span></div></div></div>
  <div className="master-toolbar"><div className="master-type-tabs">{types.filter(t=>t.active!==false).map(t=><div key={t.id} className="master-type-tab-wrap">{editingType===t.id?<><input className="master-edit-input" value={editTypeName} onChange={e=>setEditTypeName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void renameType(t)}}/><button className="mini primary" onClick={()=>void renameType(t)}>Save</button></>:<><button className={selected===t.id?"active":""} onClick={()=>{setSelected(t.id);setSearch("");setEditing(null)}}><span>{String(t.label||t.name||"Master").slice(0,3).toUpperCase()}</span>{t.label||t.name}</button><button className="mini" onClick={()=>{setEditingType(t.id);setEditTypeName(t.label||t.name)}}>Edit</button><button className="mini" onClick={()=>void toggleType(t)}>Archive</button></>}</div>)}</div><div className="master-custom"><input value={newType} onChange={e=>setNewType(e.target.value)} placeholder="New custom master e.g. Fabric Type"/><button onClick={addType} disabled={busy}>+ Add Master</button></div></div>
  <div className="master-list-card">
   <div className="master-list-head"><div><span className="eyebrow">SELECTED LIST</span><h3>{selectedType.label||selectedType.name}</h3><small>{items.length} total items · {activeItems.length} active</small></div><div className="master-actions"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search items..."/><div className="master-add"><input value={newItem} onChange={e=>setNewItem(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void addItem()}} placeholder={'Add new '+String(selectedType.label||"item").toLowerCase()+'...'}/><button className="primary" onClick={addItem} disabled={busy||!newItem.trim()}>+ Add Item</button></div></div></div>
   {filtered.length===0?<div className="master-empty"><strong>{search?"No matching items":"No items yet"}</strong><span>{search?"Try another search.":"Add the first item using the field above."}</span></div>:<div className="master-table-wrap"><table><thead><tr><th>Name</th><th>Status</th><th className="master-action-col">Actions</th></tr></thead><tbody>{filtered.map(x=><tr key={x.id}><td>{editing===x.id?<input className="master-edit-input" value={editName} onChange={e=>setEditName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void rename(x)}} autoFocus/>:<strong>{x.name}</strong>}</td><td><span className={x.active===false?"master-status inactive":"master-status"}>{x.active===false?"Archived":"Active"}</span></td><td className="master-action-col">{editing===x.id?<><button className="mini primary" onClick={()=>void rename(x)}>Save</button><button className="mini" onClick={()=>{setEditing(null);setEditName("")}}>Cancel</button></>:<><button className="mini" onClick={()=>{setEditing(x.id);setEditName(x.name)}}>Edit</button><button className="mini" onClick={()=>void toggle(x)}>{x.active===false?"Activate":"Archive"}</button></>}</td></tr>)}</tbody></table></div>}
  </div>
 </section>
}
