 const add=async()=>{if(!form.username||!form.name||form.password.length<8)return setError("Username, name and 8+ character password required.");setBusy(true);try{await apiCreateAdminUser(form);setForm({username:"",name:"",role:"cashier",password:""});await load()}catch(e){setError(e instanceof Error?e.message:"User could not be created.")}finally{setBusy(false)}};
 const toggle=async(u:any)=>{try{await apiSetAdminUserStatus(u.id,!u.active);await load()}catch(e){setError(e instanceof Error?e.message:"Status update failed.")}};
 const reset=async(u:any)=>{const password=prompt("New password (8+ characters):");if(!password)return;try{await apiSetAdminUserPassword(u.id,password);alert("Password updated.")}catch(e){setError(e instanceof Error?e.message:"Password update failed.")}};
 const createRole=async()=>{if(!roleName.trim())return;try{await apiCreateAdminRole({name:roleName.trim(),permissionCodes:selectedPerms});setRoleName("");setSelectedPerms([]);await load()}catch(e){setError(e instanceof Error?e.message:"Role could not be created.")}};
