 const requestReset=async()=>{setBusy(true);setError("");try{const r=await requestPasswordReset(username);alert(r.message)}catch(e){setError(e instanceof Error?e.message:"Reset request failed.")}finally{setBusy(false)}};
 const confirmReset=async()=>{setBusy(true);setError("");try{await confirmPasswordReset(resetToken,newPassword);alert("Password reset successful. Please log in.");setReset(false);setPassword("");setResetToken("");setNewPassword("")}catch(e){setError(e instanceof Error?e.message:"Invalid or expired reset token.")}finally{setBusy(false)}};
