function OfflineReconciliation(){
 const [items,setItems]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const run=async()=>{setBusy(true);setError("");try{if(!window.stockDoneOffline)throw new Error("Desktop offline database is unavailable.");const rows=await window.stockDoneOffline.query<any>("SELECT id,qty FROM products");const r=await reconcileOfflineStock(rows.map(x=>({variantId:x.id,quantity:Number(x.qty)})));setItems(r.differences)}catch(e){setError(e instanceof Error?e.message:"Reconciliation failed.")}finally{setBusy(false)}};
 return <section className="panel"><h2>Offline Stock Reconciliation</h2><p>Compare local offline quantities with the central server before resolving a stock conflict.</p><button onClick={run} disabled={busy}>{busy?"Checking...":"Check Stock"}</button>{error&&<p className="error">{error}</p>}{items.length>0?<table><thead><tr><th>SKU</th><th>Product</th><th>Size</th><th>Color</th><th>Local</th><th>Server</th><th>Difference</th></tr></thead><tbody>{items.map(x=><tr key={x.variant_id}><td>{x.sku}</td><td>{x.name}</td><td>{x.size||"—"}</td><td>{x.color||"—"}</td><td>{x.local_quantity??"—"}</td><td>{x.server_quantity}</td><td>{x.difference>0?"+":""}{x.difference}</td></tr>)}</tbody></table>:!busy&&!error?<p>No differences found.</p>:null}</section>
}
function OfflineSyncPanel(){
 const [rows,setRows]=useState<any[]>([]),[summary,setSummary]=useState({pending:0,failed:0,synced:0,total:0}),[busy,setBusy]=useState(false);
 const load=async()=>{try{const [c,q]=await Promise.all([getOfflineSyncConflicts(),getOfflineSyncQueueSummary()]);setRows(c);setSummary(q)}catch{setRows([])}};
 useEffect(()=>{load()},[]);
 const syncNow=async()=>{setBusy(true);try{const r=await syncAllOfflinePending();await load();alert(r.failed?"Sync completed with failures pending.":r.synced?"Sync completed successfully.":"Nothing pending to sync.");}catch(e){alert(e instanceof Error?e.message:"Sync failed.")}finally{setBusy(false)}};const retryAll=async()=>{setBusy(true);try{const r=await retryAllOfflineSync();await load();alert(r.failed?"Retry completed with failures pending.":r.synced?"Retry completed successfully.":"No failed items.");}catch(e){alert(e instanceof Error?e.message:"Retry failed.")}finally{setBusy(false)}};const retry=async(id:string)=>{setBusy(true);try{const r=await retryOfflineSyncConflict(id);await load();alert(r.synced>0?"Sync completed successfully.":"Sync could not complete; conflict remains pending.")}catch(e){alert(e instanceof Error?e.message:"Retry failed.")}finally{setBusy(false)}};
 const resolve=async(id:string)=>{if(!confirm("Acknowledge this conflict without changing server stock?"))return;try{await resolveOfflineSyncConflict(id);await load()}catch(e){alert(e instanceof Error?e.message:"Could not resolve conflict.")}};
 const pending=rows.filter(r=>r.resolution==="pending").length,retrying=rows.filter(r=>r.resolution==="retrying").length,resolved=rows.filter(r=>r.resolution==="resolved").length;
 return <section className="panel"><h2>Offline Sync</h2><p>All offline mutations drain automatically when the connection returns. Failed items remain retryable.</p><div className="grid"><section className="card"><span>Queued</span><strong>{summary.pending}</strong></section><section className="card"><span>Failed</span><strong>{summary.failed}</strong></section><section className="card"><span>Synced</span><strong>{summary.synced}</strong></section><section className="card"><span>Total</span><strong>{summary.total}</strong></section></div><button disabled={busy} onClick={syncNow}>Sync Now</button> <button disabled={busy||summary.failed===0} onClick={retryAll}>Retry Failed</button> <button onClick={load}>Refresh</button>{!rows.length?<p>No pending conflicts.</p>:<table><thead><tr><th>Date</th><th>Invoice</th><th>Status</th><th>Attempts</th><th>Error</th><th>Actions</th></tr></thead><tbody>{rows.map(r=>{let p:any={};try{p=JSON.parse(r.local_payload)}catch{};let err="Sync failed";try{err=JSON.parse(r.server_payload).error||err}catch{};return <tr key={r.id}><td>{new Date(r.detected_at).toLocaleString()}</td><td>{p.invoiceNo||r.entity_id}</td><td>{r.resolution}</td><td>{Number(r.attempts??0)}</td><td>{err}</td><td><button disabled={busy||r.resolution==="resolved"} onClick={()=>retry(r.id)}>Retry</button> <button disabled={r.resolution==="resolved"} onClick={()=>resolve(r.id)}>Acknowledge</button></td></tr>})}</tbody></table>}</section>
}
function OfflineTools(){return <><OfflineReconciliation/><OfflineSyncPanel/></>}
function ScannerInput({value,onChange,onScan}:{value:string;onChange:(v:string)=>void;onScan:(code:string)=>void}){const [focused,setFocused]=useState(false);const inputRef=useRef<HTMLInputElement|null>(null);const timerRef=useRef<number|undefined>(undefined);const valueRef=useRef(value);valueRef.current=value;const settings=getScannerSettings();const finish=()=>{const code=valueRef.current.trim();if(code){handleScannerInput(code,onScan,settings);valueRef.current="";onChange("")}};useEffect(()=>()=>{if(timerRef.current)window.clearTimeout(timerRef.current)},[]);useEffect(()=>{if(settings.autoFocus&&settings.enabled&&inputRef.current)inputRef.current.focus()},[settings.autoFocus,settings.enabled]);const key=(e:KeyboardEvent<HTMLInputElement>)=>{if(e.key==="Enter"||e.key==="Tab"){e.preventDefault();if(timerRef.current)window.clearTimeout(timerRef.current);finish();return}if(settings.delayMs>0){if(timerRef.current)window.clearTimeout(timerRef.current);timerRef.current=window.setTimeout(finish,settings.delayMs)}};return <input ref={inputRef} className="scanner" autoFocus={settings.autoFocus&&settings.enabled} disabled={!settings.enabled} value={value} onChange={e=>{valueRef.current=e.target.value;onChange(e.target.value)}} onKeyDown={key} onBlur={()=>setFocused(false)} onFocus={()=>setFocused(true)} placeholder={settings.enabled?(focused?"Ready — scan barcode":"Scan barcode"): "Barcode scanner disabled"}/>}
